-- Recovered from the linked project's Supabase migration history.

-- Truth or Dare Balanced V3: exact 948-card production catalogue.
begin;

create temporary table decked_truth_or_dare_v3(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null) on commit drop;


update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='truth-or-dare';



update public.content_item_categories set enabled=false where game_id='truth-or-dare';


commit;
